FUNCTION_BLOCK FB
VAR_INPUT
    mode            : INT;
    resetBtn        : BOOL;
    scanSeconds     : REAL;
    tempSP          : REAL;
    tempPV          : REAL;
    flowPV          : REAL;
    manualFlowSP    : REAL;
    manualValve     : REAL;
END_VAR
VAR_OUTPUT
    flowSP          : REAL;
    valveCommand    : REAL;
    fault           : BOOL;
    normalMode      : BOOL;
END_VAR
VAR
    prevResetBtn    : BOOL := FALSE;
    prevMode        : INT;
    initFlag        : BOOL := FALSE;
    iT              : REAL;
    iF              : REAL;
    prevFlowSP      : REAL;
    prevValveCmd    : REAL;
END_VAR
VAR CONSTANT
    KpT : REAL := 1.0;
    KpF : REAL := 2.0;
    KiT : REAL := 0.2;
    KiF : REAL := 0.5;
END_VAR

    fault := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);

    IF NOT initFlag OR (resetBtn AND NOT prevResetBtn) OR fault THEN
        flowSP      := manualFlowSP;
        valveCommand := manualValve;
        iT := flowSP - KpT * (tempSP - tempPV);
        iF := valveCommand - KpF * (flowSP - flowPV);
        prevMode    := mode;
        initFlag    := TRUE;
        normalMode  := FALSE;
    ELSE
        IF mode <> prevMode THEN
            prevFlowSP      := flowSP;
            prevValveCmd    := valveCommand;
            IF mode = 2 THEN
                flowSP      := prevFlowSP;
            ELSE
                flowSP      := manualFlowSP;
            END_IF
            valveCommand    := prevValveCmd;
            iT := flowSP - KpT * (tempSP - tempPV);
            iF := valveCommand - KpF * (flowSP - flowPV);
            prevMode        := mode;
            normalMode      := FALSE;
        ELSE
            IF mode = 0 THEN
                flowSP      := manualFlowSP;
                valveCommand := manualValve;
                iT := flowSP - KpT * (tempSP - tempPV);
                iF := valveCommand - KpF * (flowSP - flowPV);
            ELSIF mode = 1 THEN
                flowSP      := manualFlowSP;
                iT := flowSP - KpT * (tempSP - tempPV);
                VAR eF : REAL;
                END_VAR
                eF := flowSP - flowPV;
                iF := iF + KiF * eF * scanSeconds;
                valveCommand := LIMIT(0.0, KpF * eF + iF, 100.0);
                iF := valveCommand - KpF * eF;
            ELSIF mode = 2 THEN
                VAR eT : REAL;
                VAR eF : REAL;
                END_VAR
                eT := tempSP - tempPV;
                iT := iT + KiT * eT * scanSeconds;
                flowSP := LIMIT(0.0, KpT * eT + iT, 50.0);
                iT := flowSP - KpT * eT;
                eF := flowSP - flowPV;
                iF := iF + KiF * eF * scanSeconds;
                valveCommand := LIMIT(0.0, KpF * eF + iF, 100.0);
                iF := valveCommand - KpF * eF;
            END_IF
            normalMode := TRUE;
        END_IF
    END_IF

    prevResetBtn := resetBtn;
END_FUNCTION_BLOCK
